package mrpapermoon.whisper.contacts.dbimport androidx.room.Entityimport androidx.room.PrimaryKeyimport mrpapermoon.whisper.entity.WhispererColorimport mrpapermoon.whisper.entity.WhispererIcon@Entity(tableName = ContactEntity.TABLE_NAME)data class ContactEntity(	@PrimaryKey	val whispererId: String,	val name: String,	val color: WhispererColor,	val icon: WhispererIcon,) {	companion object {		internal const val TABLE_NAME = "contacts"	}}